import sys

class GenericStack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)
        print(f"Pushed: {item}")

    def pop(self):
        if self.is_empty():
            print("Stack is empty")
            return None
        item = self.items.pop()
        print(f"Popped: {item}")
        return item

    def peek(self):
        if self.is_empty():
            print("Stack is empty")
            return None
        print(f"Peek: {self.items[-1]}")
        return self.items[-1]

    def is_empty(self):
        return len(self.items) == 0

def main():
    stack = GenericStack()
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        command = parts[0].lower() if parts else ""
        if command == "push" and len(parts) >= 2:
            value = parts[1]
            stack.push(value)
        elif command == "pop":
            stack.pop()
        elif command == "peek":
            stack.peek()

if __name__ == "__main__":
    main()
